class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.monthly_limit_bytes = monthly_limit_mib * 1024 * 1024
        # month -> {filename: size_bytes}
        self._history: dict[str, dict[str, int]] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like '2026-01'."""
        if size_bytes <= 0:
            raise ValueError("File size must be strictly positive.")

        month_records = self._history.setdefault(month, {})

        # If the file was already uploaded in this month, it does not count towards the limit a second time.
        if name in month_records:
            return

        current_used = sum(month_records.values())
        if current_used + size_bytes > self.monthly_limit_bytes:
            raise ValueError("Upload would exceed monthly quota.")

        month_records[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        # Deleting a file does not give back quota in the current month.
        pass

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return sum(self._history.get(month, {}).values())

    def remaining_bytes(self, month: str) -> int:
        """Returns how many bytes can still be uploaded in the month."""
        return int(self.monthly_limit_bytes - self.used_bytes(month))

    def files(self) -> list[str]:
        """Returns the names of stored files, sorted."""
        filenames = {name for records in self._history.values() for name in records}
        return sorted(filenames)
```

